43	function sendEvalTableResponse(res: Response, evalId: string, responsePayload: EvalTableDTO): void {
44	  try {
45	    res.json(responsePayload);
46	  } catch (error) {
47	    if (!(error instanceof RangeError)) {
48	      throw error;
49	    }
50	
51	    logger.warn('[GET /:id/table] Response too large, stripping per-cell prompts by size', {
52	      evalId,
53	    });
54	
55	    const promptLocations = getEvalTableOutputPromptLocationsBySize(responsePayload);
56	    if (promptLocations.length === 0) {
57	      logger.error('[GET /:id/table] Response too large and has no prompts to strip', {
58	        evalId,
59	      });
60	      res.status(413).json({ error: 'Eval too large to display. Try reducing the page size.' });
61	      return;
62	    }
63	
64	    const tryStringifyWithStrippedPrompts = (promptCountToStrip: number): string | null => {
65	      const responseWithoutPrompts = getEvalTablePromptStrippedPayload(
66	        responsePayload,
67	        promptLocations,
68	        promptCountToStrip,
69	      );
70	      try {
71	        const responseBody = JSON.stringify(responseWithoutPrompts);
72	        invariant(typeof responseBody === 'string', 'Eval table response must serialize to JSON');
73	        return responseBody;
74	      } catch (retryError) {
75	        if (!(retryError instanceof RangeError)) {
76	          throw retryError;
77	        }
78	        return null;
79	      }
80	    };
81	
82	    let lowerBound = 0;
83	    let upperBound = 1;
84	    let responseBody: string | null = null;
85	
86	    while (upperBound < promptLocations.length) {
87	      responseBody = tryStringifyWithStrippedPrompts(upperBound);
88	      if (responseBody) {
89	        break;
90	      }
91	      lowerBound = upperBound;
92	      upperBound *= 2;
93	    }
94	
95	    if (!responseBody) {
96	      upperBound = promptLocations.length;
97	      responseBody = tryStringifyWithStrippedPrompts(upperBound);
98	    }
99	
100	    if (responseBody) {
101	      while (upperBound - lowerBound > 1) {
102	        const midPoint = lowerBound + Math.floor((upperBound - lowerBound) / 2);
103	        const midpointResponseBody = tryStringifyWithStrippedPrompts(midPoint);
104	        if (midpointResponseBody) {
105	          upperBound = midPoint;
106	          responseBody = midpointResponseBody;
107	        } else {
108	          lowerBound = midPoint;
109	        }
110	      }
111	
112	      res.type('json').send(responseBody);
113	      return;
114	    }
115	
116	    logger.error('[GET /:id/table] Response still too large after stripping prompts', {
117	      evalId,
118	    });
119	    res.status(413).json({ error: 'Eval too large to display. Try reducing the page size.' });
120	  }
121	}
